-- Refresh project 3 gallery with seven user-supplied architectural visualizations.
-- Upload and SHA-256 verification must complete before running.
-- Old media rows and storage objects are retained for recovery.
DO $refresh$
BEGIN
  PERFORM pg_advisory_xact_lock(31020261029);
  IF (SELECT count(*) FROM public.project_media WHERE project_id=3 AND metadata->>'import_batch'='tozon-plaza-20261029')=7 THEN
    RETURN;
  END IF;
  IF (SELECT md5(jsonb_agg(to_jsonb(m) ORDER BY id)::text) FROM public.project_media m WHERE project_id=3)
      IS DISTINCT FROM 'a9158dbcf2298265af5790d355444919' THEN
    RAISE EXCEPTION 'Project media changed since review; inspect before refreshing';
  END IF;
  IF (SELECT count(*) FROM storage.objects WHERE bucket_id='project-media' AND name LIKE 'projects/3/media/20261029/%')<>7 THEN
    RAISE EXCEPTION 'Expected all seven uploaded images';
  END IF;
  UPDATE public.project_media SET is_active=false, is_cover=false, updated_at=now()::text
  WHERE project_id=3 AND id BETWEEN 22 AND 30;
  INSERT INTO public.project_media(project_id,category,title,description,storage_path,mime_type,sort_order,is_cover,is_active,metadata,created_at,updated_at)
  SELECT 3,category,title,description,storage_path,'image/jpeg',sort_order,is_cover,true,metadata,now()::text,now()::text
  FROM jsonb_to_recordset('[{"category":"EXTERIOR","title":"TOZON PLAZA — архитектура с характером","description":"Светлый фасад, плавные угловые линии и тёплые коричневые акценты создают выразительный образ TOZON PLAZA. Этот ракурс позволяет оценить пропорции дома и его облик со стороны улицы. Представьте место, к которому приятно возвращаться каждый день. Проектная визуализация.","storage_path":"projects/3/media/20261029/img_9689.jpg","sort_order":1,"is_cover":true,"metadata":{"width":1280,"height":1024,"source_filename":"IMG_9689.JPG","sha256":"e2cfee93db4da8bb82693f6fe2aeb34cb8a62c34ce66f8faeba5cb034da16a22","byte_size":196321,"kind":"architectural_visualization","import_batch":"tozon-plaza-20261029"}},{"category":"EXTERIOR","title":"Дом в окружении зелени","description":"Фасад TOZON PLAZA в обрамлении деревьев: светлые вертикали, тёмные оконные проёмы и мягкие линии верхних этажей. Ракурс с уровня улицы передаёт масштаб здания и помогает представить свой будущий дом в городской среде. Проектная визуализация.","storage_path":"projects/3/media/20261029/img_9686.jpg","sort_order":2,"is_cover":false,"metadata":{"width":1280,"height":1024,"source_filename":"IMG_9686.JPG","sha256":"afe3471a24a057f2b0a6f5501af93d32dfc2213ac7b6ebf132c17b43e815b3da","byte_size":248816,"kind":"architectural_visualization","import_batch":"tozon-plaza-20261029"}},{"category":"EXTERIOR","title":"Плавные линии и светлый фасад","description":"Угловой ракурс раскрывает ритм окон и закруглённые элементы фасада. Сочетание светлых поверхностей и тёплого оттенка основания делает архитектуру визуально цельной — дом выглядит выразительно и вблизи, и с расстояния. Проектная визуализация.","storage_path":"projects/3/media/20261029/img_9692.jpg","sort_order":3,"is_cover":false,"metadata":{"width":1280,"height":1024,"source_filename":"IMG_9692.JPG","sha256":"f4d69e830f2e4f6d9344a5002427115309fa7779de499af63b977ed9e992d5fb","byte_size":145715,"kind":"architectural_visualization","import_batch":"tozon-plaza-20261029"}},{"category":"EXTERIOR","title":"Взгляд с улицы — детали крупным планом","description":"Вертикальные линии подчёркивают высоту здания, а плавный карниз объединяет фасад первого этажа. На этом ракурсе удобно рассмотреть архитектурные детали и представить привычный маршрут к своему новому дому. Проектная визуализация.","storage_path":"projects/3/media/20261029/img_9691.jpg","sort_order":4,"is_cover":false,"metadata":{"width":1280,"height":1024,"source_filename":"IMG_9691.JPG","sha256":"ea842d0ec9d0dde2ff25ddb3260778b65f0950c269263ddfa411193e59d969bc","byte_size":176783,"kind":"architectural_visualization","import_batch":"tozon-plaza-20261029"}},{"category":"COURTYARD","title":"Внутренняя сторона комплекса","description":"Ракурс со стороны внутреннего пространства показывает, как соединяются крылья здания. Светлые фасады, мягкие углы и зелёные акценты у основания создают спокойную композицию. Посмотрите на TOZON PLAZA с другой стороны и почувствуйте характер будущего дома. Проектная визуализация.","storage_path":"projects/3/media/20261029/img_9688.jpg","sort_order":5,"is_cover":false,"metadata":{"width":1280,"height":1024,"source_filename":"IMG_9688.JPG","sha256":"767e28dd08ccaa0712219c5115e5b55f4eb646ffc71e90a4807f78f3d804a060","byte_size":162432,"kind":"architectural_visualization","import_batch":"tozon-plaza-20261029"}},{"category":"ENTRANCE","title":"Первый этаж — встреча с домом","description":"Приближённый вид первого этажа: крупные остеклённые проёмы, тёплые оттенки облицовки и протяжённый плавный карниз. Именно с этих деталей начинается впечатление о доме — ещё до того, как Вы окажетесь в своей квартире. Проектная визуализация.","storage_path":"projects/3/media/20261029/img_9687.jpg","sort_order":6,"is_cover":false,"metadata":{"width":1280,"height":1024,"source_filename":"IMG_9687.JPG","sha256":"1a004a63a4046b2a35542f54b68257465b9e14aba49ad4cc5c292e4b3cfb7429","byte_size":162673,"kind":"architectural_visualization","import_batch":"tozon-plaza-20261029"}},{"category":"MASTERPLAN","title":"TOZON PLAZA с высоты","description":"Обзорный ракурс помогает увидеть общий объём комплекса, взаимное расположение его крыльев и архитектуру верхних этажей. Рассмотрите дом целиком, а затем выберите планировку, которая соответствует Вашему представлению о комфортной жизни. Проектная визуализация.","storage_path":"projects/3/media/20261029/img_9690.jpg","sort_order":7,"is_cover":false,"metadata":{"width":1280,"height":1024,"source_filename":"IMG_9690.JPG","sha256":"9af342447bc70002bc69aa292860990a6456dd13400dae3f448929262be8fa7a","byte_size":215820,"kind":"architectural_visualization","import_batch":"tozon-plaza-20261029"}}]'::jsonb)
  AS r(category text,title text,description text,storage_path text,sort_order integer,is_cover boolean,metadata jsonb);
END;
$refresh$;
